// householdMemberWhereR holds the relationship-based filters of
// householdMemberWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type householdMemberWhereR[Q psql.Filterable] struct {
	cols householdMemberColumns
}

// HasHousehold filters parents that have a matching Household using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Households).
func (w householdMemberWhereR[Q]) HasHousehold(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Households.NameExpr()),
		sm.Where(Households.Columns.ID.EQ(w.cols.HouseholdID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasMember filters parents that have a matching Member using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Members).
func (w householdMemberWhereR[Q]) HasMember(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Members.NameExpr()),
		sm.Where(Members.Columns.ID.EQ(w.cols.MemberID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *HouseholdMember) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("householdMember cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.HouseholdMembers = HouseholdMemberSlice{o}
		}
		return nil
	case "Member":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("householdMember cannot load %T as %q", retrieved, name)
		}

		o.R.Member = rel
		o.R.Loaded.Member = true

		if rel != nil {
			rel.R.HouseholdMembers = HouseholdMemberSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("householdMember has no relationship %q", name)
	}
}

type householdMemberPreloader struct {
	Household func(...psql.PreloadOption) psql.Preloader
	Member    func(...psql.PreloadOption) psql.Preloader
}

func buildHouseholdMemberPreloader() householdMemberPreloader {
	return householdMemberPreloader{
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        HouseholdMembers,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
		Member: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Member, MemberSlice](psql.PreloadRel{
				Name: "Member",
				Sides: []psql.PreloadSide{
					{
						From:        HouseholdMembers,
						To:          Members,
						FromColumns: []string{"member_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Members.Columns.Names(), memberScanMapperNullable, opts...)
		},
	}
}

type householdMemberThenLoader[Q orm.Loadable] struct {
	Household func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Member    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildHouseholdMemberThenLoader[Q orm.Loadable]() householdMemberThenLoader[Q] {
	type HouseholdLoadInterface interface {
		LoadHousehold(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type MemberLoadInterface interface {
		LoadMember(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return householdMemberThenLoader[Q]{
		Household: thenLoadBuilder[Q](
			"Household",
			func(ctx context.Context, exec bob.Executor, retrieved HouseholdLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadHousehold(ctx, exec, mods...)
			},
		),
		Member: thenLoadBuilder[Q](
			"Member",
			func(ctx context.Context, exec bob.Executor, retrieved MemberLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadMember(ctx, exec, mods...)
			},
		),
	}
}

// LoadHousehold loads the householdMember's Household into the .R struct
func (o *HouseholdMember) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.HouseholdMembers = HouseholdMemberSlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the householdMember's Household into the .R struct
func (os HouseholdMemberSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	householdMemberByKey := make(map[uuid.UUID][]*HouseholdMember, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		householdMemberByKey[o.HouseholdID] = append(householdMemberByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := householdMemberByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.HouseholdMembers = append(rel.R.HouseholdMembers, o)

			o.R.Household = rel

		}
	}

	return nil
}

